        for status in &["pending", "active", "paused", "resolved"] {
            let status_path = self.path.join(status);
            if status_path.exists() {
                for entry in fs::read_dir(&status_path).map_err(|e| e.to_string())? {
                    let entry = entry.map_err(|e| e.to_string())?;
                    let path = entry.path();

                    if path.extension().map_or(false, |ext| ext == "yml") {
                        let content = fs::read_to_string(&path).map_err(|e| e.to_string())?;
                        let mut task: Task = serde_yaml::from_str(&content)
                            .map_err(|e| e.to_string())?;
                        task.status = status.to_string();
                        tasks.push(task);
                    }
                }
            }
        }

        // Assign IDs based on creation time
        tasks.sort_by(|a, b| a.created.cmp(&b.created));
        for (i, task) in tasks.iter_mut().enumerate() {
            task.id = (i + 1) as u32;
        }

        Ok(tasks)
    }

    pub fn save_task(&self, task: &Task) -> Result<(), String> {
        let status_path = self.path.join(&task.status);
        fs::create_dir_all(&status_path).map_err(|e| e.to_string())?;

        let file_path = status_path.join(format!("{}.yml", task.uuid));
        let content = serde_yaml::to_string(task).map_err(|e| e.to_string())?;
        fs::write(&file_path, content).map_err(|e| e.to_string())?;

        Ok(())
    }

    pub fn delete_task(&self, task: &Task) -> Result<(), String> {
        let status_path = self.path.join(&task.status);
        let file_path = status_path.join(format!("{}.yml", task.uuid));
        fs::remove_file(file_path).map_err(|e| e.to_string())?;
        Ok(())
    }

    pub fn move_task(&self, task: &mut Task, new_status: &str) -> Result<(), String> {
        let old_path = self.path.join(&task.status).join(format!("{}.yml", task.uuid));
        let new_status_path = self.path.join(new_status);
        fs::create_dir_all(&new_status_path).map_err(|e| e.to_string())?;
        let new_path = new_status_path.join(format!("{}.yml", task.uuid));

        fs::rename(&old_path, &new_path).map_err(|e| e.to_string())?;
        task.status = new_status.to_string();
        Ok(())
    }

    pub fn git_add_all(&self) -> Result<(), String> {
        let mut index = self.git_repo.index().map_err(|e| e.to_string())?;
        index.add_all(["."].iter(), IndexAddOption::DEFAULT, None)
            .map_err(|e| e.to_string())?;
        index.write().map_err(|e| e.to_string())?;
        Ok(())
    }

    pub fn git_commit(&self, message: &str) -> Result<(), String> {
        let mut index = self.git_repo.index().map_err(|e| e.to_string())?;
        let tree_id = index.write_tree().map_err(|e| e.to_string())?;
        let tree = self.git_repo.find_tree(tree_id).map_err(|e| e.to_string())?;

        let name = std::env::var("GIT_AUTHOR_NAME").unwrap_or_else(|_| "dstask".to_string());
        let email = std::env::var("GIT_AUTHOR_EMAIL").unwrap_or_else(|_| "dstask@local".to_string());
        let sig = Signature::now(&name, &email).map_err(|e| e.to_string())?;

        let head = self.git_repo.head();
        let parents = if let Ok(head_ref) = head {
            if let Ok(obj) = head_ref.peel_to_commit() {
                vec![obj]
            } else {
                Vec::new()
            }
        } else {
            Vec::new()
        };

        let parent_refs: Vec<&git2::Commit> = parents.iter().collect();
        self.git_repo.commit(
            "HEAD",
            &sig,
            &sig,
            message,
            &tree,
            &parent_refs
        ).map_err(|e| e.to_string())?;

        Ok(())
    }

    pub fn save_context(&self, context: &str) -> Result<(), String> {
        fs::write(self.path.join(".context"), context)
            .map_err(|e| e.to_string())?;
        Ok(())
    }
}
