use crate::repo::Repository;
use crate::task::Task;
use crate::utils;
use chrono::Utc;

pub fn add_cmd(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    let mut task_args = Vec::new();
    let mut skip_context = false;

    for arg in &args[1..] {
        if arg == "--" {
            skip_context = true;
        } else {
            task_args.push(arg.clone());
        }
    }

    // Parse task summary and attributes
    let mut summary_parts = Vec::new();
    let mut tags = Vec::new();
    let mut project = String::new();
    let mut priority = "P2".to_string();
    let mut due_date_str = String::new();

    for arg in &task_args {
        if arg.starts_with('+') {
            tags.push(arg[1..].to_string());
        } else if arg.starts_with("project:") {
            project = arg[8..].to_string();
        } else if arg.starts_with("P0") || arg.starts_with("P1") || arg.starts_with("P2") || arg.starts_with("P3") {
            priority = arg.clone();
        } else if arg.starts_with("due:") {
            due_date_str = arg[4..].to_string();
        } else if arg == "template" {
            // Handle template
            continue;
        } else {
            summary_parts.push(arg.clone());
        }
    }

    let summary = summary_parts.join(" ");
    if summary.is_empty() {
        return Err("Task summary cannot be empty".to_string());
    }

    // Add context tags if not skipping
    if !skip_context && !repo.context.is_empty() {
        let ctx_parts: Vec<&str> = repo.context.split_whitespace().collect();
        for part in ctx_parts {
            if part.starts_with('+') {
                tags.push(part[1..].to_string());
            } else if part.starts_with("project:") {
                project = part[8..].to_string();
            }
        }
    }

    let mut task = Task::new(summary);
    task.tags = tags;
    task.project = project;
    task.priority = priority;
    task.status = "pending".to_string();

    // Parse due date if provided
    if !due_date_str.is_empty() {
        if let Ok(date) = chrono::NaiveDate::parse_from_str(&due_date_str, "%Y-%m-%d") {
            task.due = date.and_hms_opt(0, 0, 0).unwrap().and_utc();
        }
    }

    task.save_task(repo)?;

    // Get all tasks to find the ID
    let tasks = repo.load_all_tasks()?;
    let id = tasks.len();

    println!("\nAdded {}: {}", id, task.summary);

    // Commit to git
    repo.git_add_all()?;
    repo.git_commit(&format!("Added {}: {}", id, task.summary))?;

    println!("[38;5;245m[master");

    Ok(())
}

trait Saveable {
    fn save_task(&self, repo: &Repository) -> Result<(), String>;
}

impl Saveable for Task {
    fn save_task(&self, repo: &Repository) -> Result<(), String> {
        repo.save_task(self)
    }
}
