use serde::{Deserialize, Serialize};
use chrono::{DateTime, Utc};
use uuid::Uuid;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Task {
    pub uuid: String,
    #[serde(skip)]
    pub status: String,
    #[serde(skip)]
    pub id: u32,
    pub summary: String,
    pub notes: String,
    #[serde(default)]
    pub tags: Vec<String>,
    pub project: String,
    pub priority: String,
    #[serde(default)]
    pub delegatedto: String,
    #[serde(default)]
    pub subtasks: Vec<String>,
    #[serde(default)]
    pub dependencies: Vec<String>,
    pub created: DateTime<Utc>,
    pub resolved: DateTime<Utc>,
    pub due: DateTime<Utc>,
}

impl Task {
    pub fn new(summary: String) -> Self {
        let epoch = DateTime::<Utc>::from(std::time::UNIX_EPOCH);
        Task {
            uuid: Uuid::new_v4().to_string(),
            status: "pending".to_string(),
            id: 0,
            summary,
            notes: String::new(),
            tags: Vec::new(),
            project: String::new(),
            priority: "P2".to_string(),
            delegatedto: String::new(),
            subtasks: Vec::new(),
            dependencies: Vec::new(),
            created: Utc::now(),
            resolved: epoch,
            due: epoch,
        }
    }

    pub fn to_json_with_status(&self) -> serde_json::Value {
        let mut value = serde_json::to_value(self).unwrap();
        if let Some(obj) = value.as_object_mut() {
            obj.insert("status".to_string(), serde_json::json!(self.status));
            obj.insert("id".to_string(), serde_json::json!(self.id));
        }
        value
    }
}
