fn cmd_show_paused(repo: &Repository) -> Result<(), String> {
    let all_tasks = repo.load_all_tasks()?;
    let mut paused_tasks: Vec<Task> = all_tasks.iter()
        .filter(|t| t.status == "paused")
        .cloned()
        .collect();

    paused_tasks.sort_by(|a, b| a.created.cmp(&b.created));

    let json: Vec<serde_json::Value> = paused_tasks.iter()
