        .collect();

    println!("{}", serde_json::to_string_pretty(&json).unwrap());

    Ok(())
}

fn cmd_show_tags(repo: &Repository) -> Result<(), String> {
    let all_tasks = repo.load_all_tasks()?;
    let mut tags = std::collections::HashSet::new();

    for task in all_tasks {
        for tag in task.tags {
            tags.insert(tag);
        }
    }

    let mut tags_vec: Vec<String> = tags.into_iter().collect();
    tags_vec.sort();

    for tag in tags_vec {
        println!("{}", tag);
    }

    Ok(())
}

fn cmd_show_projects(repo: &Repository) -> Result<(), String> {
    let all_tasks = repo.load_all_tasks()?;
    let mut projects = HashMap::new();

    for task in all_tasks {
        if !task.project.is_empty() {
            let entry = projects.entry(task.project).or_insert((0, 0));
            entry.0 += 1;
            if task.status == "resolved" {
                entry.1 += 1;
            }
        }
    }

    let mut projects_vec: Vec<_> = projects.into_iter().collect();
    projects_vec.sort_by(|a, b| a.0.cmp(&b.0));

    for (project, (total, resolved)) in projects_vec {
        let pct = if total > 0 { (resolved * 100) / total } else { 0 };
        println!("{} ({}/{})", project, resolved, total);
    }

    Ok(())
}

