}

fn cmd_start(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    let ids = parse_ids(args)?;
    let mut all_tasks = repo.load_all_tasks()?;

    for id in ids {
        if let Some(task) = all_tasks.iter_mut().find(|t| t.id == id) {
            if task.status != "active" {
                let old_status = task.status.clone();
                repo.move_task(&old_status, &task.uuid, "active")?;
                task.status = "active".to_string();
                repo.save_task(task)?;

                println!("\nStarted {}: {}", id, task.summary);
            }
        }
    }

    repo.git_add_all()?;
    if ids.len() > 0 {
        let first_id = ids[0];
        if let Some(task) = all_tasks.iter().find(|t| t.id == first_id) {
            print!("\x1b[38;5;245m");
            repo.git_commit(&format!("Started {}: {}", first_id, task.summary))?;
            print!("\x1b[0m");
        }
    }

    Ok(())
}

fn cmd_stop(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    let ids = parse_ids(args)?;
    let mut all_tasks = repo.load_all_tasks()?;

    for id in ids {
        if let Some(task) = all_tasks.iter_mut().find(|t| t.id == id) {
            if task.status != "paused" {
                let old_status = task.status.clone();
                repo.move_task(&old_status, &task.uuid, "paused")?;
                task.status = "paused".to_string();
                repo.save_task(task)?;

                println!("\nStopped {}: {}", id, task.summary);
            }
        }
    }

    repo.git_add_all()?;
    if ids.len() > 0 {
        let first_id = ids[0];
        if let Some(task) = all_tasks.iter().find(|t| t.id == first_id) {
            print!("\x1b[38;5;245m");
            repo.git_commit(&format!("Stopped {}: {}", first_id, task.summary))?;
            print!("\x1b[0m");
        }
    }

    Ok(())
}

fn cmd_done(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    let ids = parse_ids(args)?;
    let mut all_tasks = repo.load_all_tasks()?;

    for id in ids {
        if let Some(task) = all_tasks.iter_mut().find(|t| t.id == id) {
            if task.status != "resolved" {
                let old_status = task.status.clone();
                task.resolved = Utc::now();
                repo.move_task(&old_status, &task.uuid, "resolved")?;
                task.status = "resolved".to_string();
                repo.save_task(task)?;

                println!("\nResolved {}: {}", id, task.summary);
            }
        }
    }

    repo.git_add_all()?;
    if ids.len() > 0 {
        let first_id = ids[0];
        if let Some(task) = all_tasks.iter().find(|t| t.id == first_id) {
            print!("\x1b[38;5;245m");
            repo.git_commit(&format!("Resolved {}: {}", first_id, task.summary))?;
            print!("\x1b[0m");
        }
    }

    Ok(())
}

fn cmd_remove(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    let ids = parse_ids(args)?;
    let mut all_tasks = repo.load_all_tasks()?;

    for id in ids {
        if let Some(task) = all_tasks.iter_mut().find(|t| t.id == id) {
            repo.delete_task(&task.status, &task.uuid)?;
            println!("\nRemoved {}: {}", id, task.summary);
        }
    }

    repo.git_add_all()?;
    if ids.len() > 0 {
        print!("\x1b[38;5;245m");
        repo.git_commit("Removed task")?;
        print!("\x1b[0m");
    }

    Ok(())
}

fn cmd_context(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    if args.is_empty() {
        println!("{}", repo.context);
        return Ok(());
    }

    let mut context_str = args.join(" ");

    if context_str == "none" {
