fn parse_ids(args: &[String]) -> Result<Vec<u32>, String> {
    let mut ids = Vec::new();

    for arg in args {
        if let Ok(id) = arg.parse::<u32>() {
            ids.push(id);
        } else if arg == "--" {
            break;
        } else if !arg.starts_with('-') && !arg.starts_with('+') && !arg.starts_with("project:") &&
                  !arg.starts_with("P") {
            break;
        }
    }

    if ids.is_empty() {
        return Err("No task IDs specified".to_string());
    }

    Ok(ids)
}

fn matches_context(task: &Task, context: &str) -> bool {
    let parts: Vec<&str> = context.split_whitespace().collect();

    for part in parts {
        if part.starts_with('+') {
            let tag = &part[1..];
            if !task.tags.contains(&tag.to_string()) {
                return false;
            }
        } else if part.starts_with("project:") {
            let proj = &part[8..];
            if task.project != proj {
                return false;
            }
        }
    }

    true
}

