fn cmd_add(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    let mut task_args = Vec::new();
    let mut skip_context = false;

    for arg in args {
        if arg == "--" {
            skip_context = true;
        } else if !skip_context || task_args.len() > 0 {
            task_args.push(arg.clone());
        }
    }

    let mut summary_parts = Vec::new();
    let mut tags = Vec::new();
    let mut project = String::new();
    let mut priority = "P2".to_string();
    let mut due_date_str = String::new();

    for arg in &task_args {
        if arg.starts_with('+') {
            tags.push(arg[1..].to_string());
        } else if arg.starts_with("project:") {
            project = arg[8..].to_string();
        } else if arg.starts_with("P0") || arg.starts_with("P1") || arg.starts_with("P2") || arg.starts_with("P3") {
            priority = arg.clone();
        } else if arg.starts_with("due:") {
            due_date_str = arg[4..].to_string();
        } else {
            summary_parts.push(arg.clone());
        }
    }

    let summary = summary_parts.join(" ");
    if summary.is_empty() {
        return Err("Task summary cannot be empty".to_string());
    }

    // Add context tags if not skipping and context exists
    if !skip_context && !repo.context.is_empty() {
        let ctx_parts: Vec<&str> = repo.context.split_whitespace().collect();
        for part in ctx_parts {
            if part.starts_with('+') {
                let tag = part[1..].to_string();
                if !tags.contains(&tag) {
                    tags.push(tag);
                }
            } else if part.starts_with("project:") {
                if project.is_empty() {
                    project = part[8..].to_string();
                }
            }
        }
    }

    let mut task = Task::new(summary.clone());
    task.tags = tags;
    task.project = project;
    task.priority = priority;
    task.status = "pending".to_string();

    if !due_date_str.is_empty() {
        if let Ok(date) = chrono::NaiveDate::parse_from_str(&due_date_str, "%Y-%m-%d") {
            task.due = date.and_hms_opt(0, 0, 0).unwrap().and_utc();
        }
    }

    repo.save_task(&task)?;

    // Get all tasks to find the ID
    let all_tasks = repo.load_all_tasks()?;
    let id = all_tasks.len();

    println!("\nAdded {}: {}", id, summary);

    repo.git_add_all()?;
    print!("\x1b[38;5;245m");
    repo.git_commit(&format!("Added {}: {}", id, summary))?;
    print!("\x1b[0m");

    Ok(())
}

fn cmd_next(repo: &Repository) -> Result<(), String> {
    let all_tasks = repo.load_all_tasks()?;
    let mut open_tasks: Vec<Task> = all_tasks.iter()
        .filter(|t| t.status != "resolved")
        .cloned()
        .collect();

    // Apply context filter if set
    if !repo.context.is_empty() {
        open_tasks.retain(|t| matches_context(t, &repo.context));
    }

    // Sort by priority then creation date
    open_tasks.sort_by(|a, b| {
        let priority_cmp = a.priority_sort_order().cmp(&b.priority_sort_order());
        if priority_cmp != std::cmp::Ordering::Equal {
            priority_cmp
        } else {
            a.created.cmp(&b.created)
        }
    });

    let json: Vec<serde_json::Value> = open_tasks.iter()
        .map(|t| t.to_json_with_status())
        .collect();

    println!("{}", serde_json::to_string_pretty(&json).unwrap());

    Ok(())
}

