    repo.git_add_all()?;
    if ids.len() > 0 {
        print!("\x1b[38;5;245m");
        repo.git_commit("Removed task")?;
        print!("\x1b[0m");
    }

    Ok(())
}

fn cmd_context(repo: &mut Repository, args: &[String]) -> Result<(), String> {
    if args.is_empty() {
        println!("{}", repo.context);
        return Ok(());
    }

    let mut context_str = args.join(" ");

    if context_str == "none" {
        context_str = String::new();
    }

    // Validate context doesn't contain plain text
    let parts: Vec<&str> = context_str.split_whitespace().collect();
    for part in &parts {
        if !part.starts_with('+') && !part.starts_with('-') && !part.starts_with("project:") &&
           !part.starts_with("P0") && !part.starts_with("P1") && !part.starts_with("P2") && !part.starts_with("P3") {
            return Err("context cannot contain text".to_string());
        }
    }

    repo.save_context(&context_str)?;

    Ok(())
}

