fn handle_command(args: &[String], repo_path: &PathBuf) -> Result<(), String> {
    if args.is_empty() {
        return cmd_next(repo_path);
    }

    let mut cmd = args[0].as_str();
    let mut args_remain = &args[1..];

    // Handle case where first arg is an ID
