        "show-templates" => cmd_show_templates(repo_path),
        "show-unorganised" => cmd_show_unorganised(repo_path),
        "start" => cmd_start(repo_path, args),
        "stop" => cmd_stop(repo_path, args),
        "done" | "resolve" => cmd_done(repo_path, args),
        "remove" | "rm" => cmd_remove(repo_path, args),
        "context" => cmd_context(repo_path, args_remain),
        "log" => cmd_log(repo_path, args_remain),
        "modify" => cmd_modify(repo_path, args),
        "edit" => cmd_edit(repo_path, args),
        "note" | "notes" => cmd_note(repo_path, args),
        "template" => cmd_template(repo_path, args_remain),
        "open" => cmd_open(repo_path, args),
        "undo" => cmd_undo(repo_path, args_remain),
        "sync" => cmd_sync(repo_path),
