fn cmd_modify(repo_path: &PathBuf, args: &[String]) -> Result<(), String> {
    init_repo(repo_path)?;

    let ids = parse_ids(args)?;
    let mut tasks = load_all_tasks(repo_path)?;

    // Extract modification parameters
    let mut mod_tags = Vec::new();
    let mut remove_tags = Vec::new();
    let mut mod_project = None;
    let mut mod_priority = None;

    for arg in args {
        if arg.starts_with('+') {
            mod_tags.push(arg[1..].to_string());
        } else if arg.starts_with('-') && arg.len() > 1 && arg.chars().nth(1).unwrap().is_alphabetic() {
            remove_tags.push(arg[1..].to_string());
        } else if arg.starts_with("project:") {
            mod_project = Some(arg[8..].to_string());
        } else if arg.starts_with("-project:") {
            mod_project = Some(String::new());
        } else if arg.starts_with("P0") || arg.starts_with("P1") || arg.starts_with("P2") || arg.starts_with("P3") {
            mod_priority = Some(arg.to_string());
        }
    }

    for id in ids {
        if let Some(task) = tasks.iter_mut().find(|t| t.id == id) {
            for tag in &mod_tags {
                if !task.tags.contains(tag) {
                    task.tags.push(tag.clone());
                }
            }
            for tag in &remove_tags {
                task.tags.retain(|t| t != tag);
            }
            if let Some(ref proj) = mod_project {
                task.project = proj.clone();
            }
            if let Some(ref pri) = mod_priority {
                task.priority = pri.clone();
            }

            save_task(repo_path, task)?;
            println!("Modified {}", id);
        }
    }

    run_git_add(repo_path)?;
    run_git_commit(repo_path, "Modified task")?;

    Ok(())
