fn cmd_add(repo_path: &PathBuf, args: &[String]) -> Result<(), String> {
    let mut summary_parts = Vec::new();
    let mut tags = Vec::new();
    let mut project = String::new();
    let mut priority = "P2".to_string();
    let mut due_date_str = String::new();
    let mut skip_context = false;

    // Initialize repository
    init_repo(repo_path)?;

    // Load context
    let context = fs::read_to_string(repo_path.join(".context"))
        .unwrap_or_default()
        .trim()
        .to_string();

    for arg in args {
        if arg == "--" {
            skip_context = true;
        } else if arg.starts_with('+') {
            tags.push(arg[1..].to_string());
        } else if arg.starts_with("project:") {
            project = arg[8..].to_string();
        } else if arg.starts_with("P0") || arg.starts_with("P1") || arg.starts_with("P2") || arg.starts_with("P3") {
            priority = arg.clone();
        } else if arg.starts_with("due:") {
            due_date_str = arg[4..].to_string();
        } else {
            summary_parts.push(arg.clone());
        }
    }

    // Apply context
    if !skip_context && !context.is_empty() {
        let ctx_parts: Vec<&str> = context.split_whitespace().collect();
        for part in ctx_parts {
            if part.starts_with('+') {
                let tag = part[1..].to_string();
                if !tags.contains(&tag) {
                    tags.push(tag);
                }
            } else if part.starts_with("project:") && project.is_empty() {
                project = part[8..].to_string();
            }
        }
    }

    let summary = summary_parts.join(" ");
    if summary.is_empty() {
        return Err("Task summary cannot be empty".to_string());
    }

    // Create YAML task
    let uuid = generate_uuid();
    let now = get_iso_timestamp();
    let due_timestamp = if due_date_str.is_empty() {
        "0001-01-01T00:00:00Z".to_string()
    } else {
        format!("{}T00:00:00Z", due_date_str)
    };

    let mut yaml_content = format!(
        "summary: {}\nnotes: \"\"\ntags:\n",
        summary
    );

    for tag in &tags {
        yaml_content.push_str(&format!("- {}\n", tag));
    }

    yaml_content.push_str(&format!(
        "project: {}\npriority: {}\ndelegatedto: \"\"\nsubtasks: []\ndependencies: []\ncreated: {}\nresolved: 0001-01-01T00:00:00Z\ndue: {}\n",
        project, priority, now, due_timestamp
    ));

    let task_file = repo_path.join("pending").join(format!("{}.yml", uuid));
    fs::write(task_file, yaml_content).map_err(|e| e.to_string())?;

    // Get task ID
    let tasks = load_all_tasks(repo_path)?;
    let id = tasks.len();

    println!("\nAdded {}: {}", id, summary);

    // Commit to git
    run_git_add(repo_path)?;
    print!("\x1b[38;5;245m");
    run_git_commit(repo_path, &format!("Added {}: {}", id, summary))?;
    print!("\x1b[0m");

    Ok(())
}

fn cmd_next(repo_path: &PathBuf) -> Result<(), String> {
    init_repo(repo_path)?;

    let mut tasks = load_all_tasks(repo_path)?;

    // Filter out resolved
    tasks.retain(|t| t.status != "resolved");

    // Apply context
    let context = fs::read_to_string(repo_path.join(".context"))
        .unwrap_or_default()
        .trim()
        .to_string();

    if !context.is_empty() {
        tasks.retain(|t| matches_context(&t, &context));
    }

    // Sort by priority then creation date
    tasks.sort_by(|a, b| {
        let priority_cmp = priority_sort_order(&a.priority).cmp(&priority_sort_order(&b.priority));
        if priority_cmp != std::cmp::Ordering::Equal {
            priority_cmp
        } else {
            a.created.cmp(&b.created)
        }
    });

    print_tasks_json(&tasks);

    Ok(())
}

