fn cmd_start(repo_path: &PathBuf, args: &[String]) -> Result<(), String> {
    init_repo(repo_path)?;

    let ids = parse_ids(args)?;
    let mut tasks = load_all_tasks(repo_path)?;

    for id in &ids {
        if let Some(task) = tasks.iter_mut().find(|t| t.id == *id) {
            if task.status != "active" {
                let old_status = task.status.clone();
                move_task(repo_path, &old_status, &task.uuid, "active")?;
                task.status = "active".to_string();
                println!("\nStarted {}: {}", id, task.summary);
            }
        }
    }

    run_git_add(repo_path)?;
    if let Some(task) = tasks.iter().find(|t| t.id == ids[0]) {
        print!("\x1b[38;5;245m");
        run_git_commit(repo_path, &format!("Started {}: {}", ids[0], task.summary))?;
        print!("\x1b[0m");
    }

    Ok(())
}

