                let old_status = task.status.clone();
                task.resolved = get_iso_timestamp();
                move_task(repo_path, &old_status, &task.uuid, "resolved")?;

                // Update file with resolved timestamp
                save_task(repo_path, task)?;

                task.status = "resolved".to_string();
                println!("\nResolved {}: {}", id, task.summary);
            }
        }
    }

    run_git_add(repo_path)?;
    if let Some(task) = tasks.iter().find(|t| t.id == ids[0]) {
        print!("\x1b[38;5;245m");
        run_git_commit(repo_path, &format!("Resolved {}: {}", ids[0], task.summary))?;
        print!("\x1b[0m");
    }

    Ok(())
}

