// Helper structures and functions

#[derive(Clone)]
struct Task {
    uuid: String,
    status: String,
    id: u32,
    summary: String,
    notes: String,
    tags: Vec<String>,
    project: String,
    priority: String,
    delegatedto: String,
    created: String,
    resolved: String,
    due: String,
}

fn init_repo(repo_path: &PathBuf) -> Result<(), String> {
    fs::create_dir_all(repo_path).map_err(|e| e.to_string())?;
    fs::create_dir_all(repo_path.join("pending")).ok();
    fs::create_dir_all(repo_path.join("active")).ok();
    fs::create_dir_all(repo_path.join("paused")).ok();
    fs::create_dir_all(repo_path.join("resolved")).ok();

    if !repo_path.join(".git").exists() {
        std::process::Command::new("git")
            .arg("init")
            .current_dir(repo_path)
            .output()
            .map_err(|e| e.to_string())?;
    }

    Ok(())
}

fn load_all_tasks(repo_path: &PathBuf) -> Result<Vec<Task>, String> {
    let mut tasks = Vec::new();

    for status in &["pending", "active", "paused", "resolved"] {
        let status_path = repo_path.join(status);
        if status_path.exists() {
            for entry in fs::read_dir(&status_path).map_err(|e| e.to_string())? {
                let entry = entry.map_err(|e| e.to_string())?;
                let path = entry.path();

                if path.extension().map_or(false, |ext| ext == "yml") {
                    let filename = path.file_stem()
                        .and_then(|s| s.to_str())
                        .unwrap_or("")
                        .to_string();

                    let content = fs::read_to_string(&path).map_err(|e| e.to_string())?;
                    if let Ok(mut task) = parse_yaml_task(&content, status) {
                        task.uuid = filename;
                        tasks.push(task);
                    }
                }
            }
        }
    }

    tasks.sort_by(|a, b| a.created.cmp(&b.created));
    for (i, task) in tasks.iter_mut().enumerate() {
        task.id = (i + 1) as u32;
    }

    Ok(tasks)
}

fn parse_yaml_task(content: &str, status: &str) -> Result<Task, String> {
    let mut task = Task {
        uuid: String::new(),
        status: status.to_string(),
        id: 0,
        summary: String::new(),
        notes: String::new(),
        tags: Vec::new(),
        project: String::new(),
        priority: "P2".to_string(),
        delegatedto: String::new(),
        created: String::new(),
        resolved: String::new(),
        due: String::new(),
    };

    for line in content.lines() {
        if line.starts_with("summary: ") {
            task.summary = line[9..].to_string();
        } else if line.starts_with("notes: ") {
            task.notes = line[7..].trim_matches('"').to_string();
        } else if line.starts_with("- ") && !line.starts_with("- ") {
            // tags line
        } else if line.starts_with("- ") {
            task.tags.push(line[2..].to_string());
        } else if line.starts_with("project: ") {
            task.project = line[9..].to_string();
        } else if line.starts_with("priority: ") {
            task.priority = line[10..].to_string();
        } else if line.starts_with("delegatedto: ") {
            task.delegatedto = line[13..].trim_matches('"').to_string();
        } else if line.starts_with("created: ") {
            task.created = line[9..].to_string();
        } else if line.starts_with("resolved: ") {
            task.resolved = line[10..].to_string();
        } else if line.starts_with("due: ") {
            task.due = line[5..].to_string();
        }
    }

    Ok(task)
}

fn save_task(repo_path: &PathBuf, task: &Task) -> Result<(), String> {
    let status_path = repo_path.join(&task.status);
    fs::create_dir_all(&status_path).map_err(|e| e.to_string())?;

    let file_path = status_path.join(format!("{}.yml", task.uuid));

    let yaml_content = format!(
        "summary: {}\nnotes: \"\"\ntags:\n{}\nproject: {}\npriority: {}\ndelegatedto: \"\"\nsubtasks: []\ndependencies: []\ncreated: {}\nresolved: {}\ndue: {}\n",
        task.summary,
        task.tags.iter().map(|t| format!("- {}\n", t)).collect::<String>(),
        task.project,
        task.priority,
        task.created,
        task.resolved,
        task.due
    );

    fs::write(&file_path, yaml_content).map_err(|e| e.to_string())?;

    Ok(())
}

fn move_task(repo_path: &PathBuf, old_status: &str, uuid: &str, new_status: &str) -> Result<(), String> {
    let old_path = repo_path.join(old_status).join(format!("{}.yml", uuid));
    let new_status_path = repo_path.join(new_status);
    fs::create_dir_all(&new_status_path).map_err(|e| e.to_string())?;
    let new_path = new_status_path.join(format!("{}.yml", uuid));

    fs::rename(&old_path, &new_path).map_err(|e| e.to_string())?;
    Ok(())
}

fn run_git_add(repo_path: &PathBuf) -> Result<(), String> {
    std::process::Command::new("git")
        .arg("add")
        .arg(".")
        .current_dir(repo_path)
        .output()
        .map_err(|e| e.to_string())?;
    Ok(())
}

fn run_git_commit(repo_path: &PathBuf, message: &str) -> Result<(), String> {
    let output = std::process::Command::new("git")
        .arg("commit")
        .arg("-m")
        .arg(message)
        .current_dir(repo_path)
        .output()
        .map_err(|e| e.to_string())?;

    let stderr = String::from_utf8_lossy(&output.stderr);
    let stdout = String::from_utf8_lossy(&output.stdout);

    if !stderr.is_empty() {
        println!("{}", stderr);
    }
    if !stdout.is_empty() {
        println!("{}", stdout);
    }

    Ok(())
}

fn parse_ids(args: &[String]) -> Result<Vec<u32>, String> {
    let mut ids = Vec::new();

    for arg in args {
        if let Ok(id) = arg.parse::<u32>() {
            ids.push(id);
        } else if arg == "--" {
            break;
        } else if !arg.starts_with('-') && !arg.starts_with('+') && !arg.starts_with("project:") &&
                  !arg.starts_with("P") {
            break;
        }
    }

    if ids.is_empty() {
        return Err("No task IDs specified".to_string());
    }

    Ok(ids)
}

fn generate_uuid() -> String {
    use std::collections::hash_map::DefaultHasher;
    use std::hash::{Hash, Hasher};

    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap();

    let mut hasher = DefaultHasher::new();
    now.hash(&mut hasher);
    let hash = hasher.finish();

    format!("{:08x}-{:04x}-{:04x}-{:04x}-{:012x}",
        (hash >> 32) as u32,
        ((hash >> 16) & 0xFFFF) as u16,
        (hash & 0xFFFF) as u16,
        ((hash >> 48) & 0xFFFF) as u16,
        hash
    )
}

fn get_iso_timestamp() -> String {
    let now = std::time::SystemTime::now();
    let duration = now.duration_since(std::time::UNIX_EPOCH).unwrap();
    let secs = duration.as_secs();
    let nanos = duration.subsec_nanos();

    // Simple RFC3339 formatting
    let days_since_epoch = secs / 86400;
    let secs_today = secs % 86400;

    let year = 1970 + (days_since_epoch / 365);
    let day_of_year = (days_since_epoch % 365) as u32;
    let month = (day_of_year / 30) + 1;
    let day = (day_of_year % 30) + 1;

    let hours = secs_today / 3600;
    let minutes = (secs_today % 3600) / 60;
    let seconds = secs_today % 60;

    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:09}Z",
        year, month, day, hours, minutes, seconds, nanos)
}

fn print_tasks_json(tasks: &[Task]) {
    print!("[");
    for (i, task) in tasks.iter().enumerate() {
        if i > 0 {
            print!(",");
        }
        print!("\n  {{\n    \"uuid\": \"{}\",\n    \"status\": \"{}\",\n    \"id\": {},\n    \"summary\": \"{}\",\n    \"notes\": \"{}\",\n    \"tags\": [",
            task.uuid,
            task.status,
            task.id,
            task.summary,
            task.notes
        );
        for (j, tag) in task.tags.iter().enumerate() {
            if j > 0 {
                print!(",");
            }
            print!("\n      \"{}\"", tag);
        }
        println!("\n    ],\n    \"project\": \"{}\",\n    \"priority\": \"{}\",\n    \"created\": \"{}\",\n    \"resolved\": \"{}\",\n    \"due\": \"{}\"",
            task.project,
            task.priority,
            task.created,
            task.resolved,
            task.due
        );
        print!("  }}");
    }
    println!("\n]");
}

fn priority_sort_order(priority: &str) -> u32 {
    match priority {
        "P0" => 0,
        "P1" => 1,
        "P2" => 2,
        "P3" => 3,
        _ => 2,
    }
}

fn matches_context(task: &Task, context: &str) -> bool {
    let parts: Vec<&str> = context.split_whitespace().collect();

    for part in parts {
        if part.starts_with('+') {
            let tag = &part[1..];
            if !task.tags.contains(&tag.to_string()) {
                return false;
            }
        } else if part.starts_with("project:") {
            let proj = &part[8..];
            if task.project != proj {
                return false;
            }
        }
    }

    true
}
