fn cmd_start(repo_path: &PathBuf, args: &[String]) -> Result<(), String> {
    init_repo(repo_path)?;

    let ids = parse_ids(args)?;
    let mut tasks = load_all_tasks(repo_path)?;

    for id in &ids {
        if let Some(task) = tasks.iter_mut().find(|t| t.id == *id) {
            if task.status != "active" {
                let old_status = task.status.clone();
                move_task(repo_path, &old_status, &task.uuid, "active")?;
                task.status = "active".to_string();
                println!("\nStarted {}: {}", id, task.summary);
            }
        }
    }

    run_git_add(repo_path)?;
    if let Some(task) = tasks.iter().find(|t| t.id == ids[0]) {
        print!("\x1b[38;5;245m");
        run_git_commit(repo_path, &format!("Started {}: {}", ids[0], task.summary))?;
        print!("\x1b[0m");
    }

    Ok(())
}

fn cmd_stop(repo_path: &PathBuf, args: &[String]) -> Result<(), String> {
    init_repo(repo_path)?;

    let ids = parse_ids(args)?;
    let mut tasks = load_all_tasks(repo_path)?;

    for id in &ids {
        if let Some(task) = tasks.iter_mut().find(|t| t.id == *id) {
            if task.status != "paused" {
                let old_status = task.status.clone();
                move_task(repo_path, &old_status, &task.uuid, "paused")?;
                task.status = "paused".to_string();
                println!("\nStopped {}: {}", id, task.summary);
            }
        }
    }

    run_git_add(repo_path)?;
    if let Some(task) = tasks.iter().find(|t| t.id == ids[0]) {
        print!("\x1b[38;5;245m");
        run_git_commit(repo_path, &format!("Stopped {}: {}", ids[0], task.summary))?;
        print!("\x1b[0m");
    }

    Ok(())
}

fn cmd_done(repo_path: &PathBuf, args: &[String]) -> Result<(), String> {
    init_repo(repo_path)?;

    let ids = parse_ids(args)?;
    let mut tasks = load_all_tasks(repo_path)?;

    for id in &ids {
        if let Some(task) = tasks.iter_mut().find(|t| t.id == *id) {
            if task.status != "resolved" {
                let old_status = task.status.clone();
                task.resolved = get_iso_timestamp();
                move_task(repo_path, &old_status, &task.uuid, "resolved")?;

                // Update file with resolved timestamp
                save_task(repo_path, task)?;

                task.status = "resolved".to_string();
                println!("\nResolved {}: {}", id, task.summary);
            }
        }
    }

    run_git_add(repo_path)?;
    if let Some(task) = tasks.iter().find(|t| t.id == ids[0]) {
        print!("\x1b[38;5;245m");
        run_git_commit(repo_path, &format!("Resolved {}: {}", ids[0], task.summary))?;
        print!("\x1b[0m");
    }

    Ok(())
}

fn cmd_remove(repo_path: &PathBuf, args: &[String]) -> Result<(), String> {
